@propertyWrapper struct Clamped {
    var v: Int
    var wrappedValue: Int {
        get { v }
        set { v = min(newValue, 10) }
    }
    init(wrappedValue: Int) { v = min(wrappedValue, 10) }
}
struct S { @Clamped var n = 50 }
var s = S()
s.n = 99
print(s.n)

